select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Manychat AI' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Automatisation des conversations sur Instagram, WhatsApp, Messenger et TikTok, avec une IA qui reconnaît les intentions, répond aux abonnés et mène les conversations de vente.',
  'Chat automation for Instagram, WhatsApp, Messenger and TikTok, with AI that recognizes intent, answers followers and runs sales conversations.');
