select refresh_rankings();

select e.name, 'https://electraindex.com/agents/' || e.slug as page,
       (select count(*) from entities x where x.type = 'agent' and x.is_published) as agents_total
  from entities e where e.type = 'agent' and e.name in ('Manychat AI', 'CustomGPT.ai', 'My AI Front Desk', 'Rosie', 'Tasklet', 'Quadratic AI', 'Koala AI', 'goose', 'OpenCode', 'DocsBot AI', 'Cosine', 'Workable Agents', 'Upfirst') order by e.name;
